  stmts := ARRAY_APPEND(:stmts, REPLACE(REPLACE('DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20072,''Existing app requires explicit migration; source is preserved''); BEGIN SHOW STREAMLITS LIKE ''DATA_QUALITY_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''DATA_QUALITY_APP''; IF (:present_count>0) THEN SHOW STREAMLITS LIKE ''DATA_QUALITY_APP'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''DATA_QUALITY_APP'' AND "comment"=''oneshot-source:12_data_quality''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE STREAMLIT __TARGET__.DATA_QUALITY_APP FROM ''@__TARGET__.APP_STAGE/source/085e6353e72c69cc/'' MAIN_FILE=''streamlit_app.py'' QUERY_WAREHOUSE=__WAREHOUSE__ RUNTIME_NAME=''SYSTEM$WAREHOUSE_RUNTIME'' COMMENT=''oneshot-source:12_data_quality''; ALTER STREAMLIT __TARGET__.DATA_QUALITY_APP ADD LIVE VERSION FROM LAST; END IF; END', '__TARGET__', :tgt), '__WAREHOUSE__', :wh));
  stmts := ARRAY_APPEND(:stmts, REPLACE('BEGIN DECLARE present_count INTEGER; owned_count INTEGER; collision EXCEPTION (-20071,''ONESHOT_SOURCE belongs to a different installation''); BEGIN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :present_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE''; IF (:present_count>0) THEN SHOW WORKSPACES LIKE ''ONESHOT_SOURCE'' IN SCHEMA __TARGET__; SELECT COUNT(*) INTO :owned_count FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"=''ONESHOT_SOURCE'' AND "comment"=''oneshot-source:12_data_quality''; IF (:owned_count<>1) THEN RAISE collision; END IF; ELSE CREATE WORKSPACE __TARGET__.ONESHOT_SOURCE COMMENT=''oneshot-source:12_data_quality''; ALTER WORKSPACE __TARGET__.ONESHOT_SOURCE ADD LIVE VERSION FROM LAST; COPY FILES INTO ''snow://workspace/__TARGET__.ONESHOT_SOURCE/versions/live/'' FROM @__TARGET__.APP_STAGE/source/085e6353e72c69cc/; END IF; END; EXCEPTION WHEN OTHER THEN NULL; END', '__TARGET__', :tgt));
  notes := ARRAY_APPEND(:notes, 'Editable source: ' || :tgt || '.ONESHOT_SOURCE. Existing workspace and app source are preserved on rerun.');
